({__plugin:null,__load(){if(this.__plugin)return this.__plugin;this.__plugin=function(){"use strict";let locales=unbound.i18n.createLocales({LEAVE_SILENT_DESC:"Leave this group DM without notifying the other members"});function leaveUrl(channelId){return`/channels/${channelId}`}function registerLeaveSilent(){unbound.commands.register({"leave-silent":{description:"LEAVE_SILENT_DESC",execute:async(_options,param)=>{var{channel}=param;if(3!==channel.type)return{ephemeral:!0,content:"This only works in a group DM."};var{REST}=unbound.metro.common;if(!REST?.del)return logger.warn("Silent leave failed: Discord moved its REST client."),{ephemeral:!0,content:"Could not leave: Discord changed its API client."};try{await REST.del({url:leaveUrl(channel.id),query:"silent=true"})}catch(error){return logger.error("Silent leave failed:",error),{ephemeral:!0,content:"Failed to leave the group DM."}}return{ephemeral:!0,content:"Left the group DM silently."}}}})}return locales.messages,locales.format,locales.useMessages,{start:function start(){registerLeaveSilent()},stop:function stop(){unbound.patcher.unpatchAll()}}}();return this.__plugin;}})